const cfg = $input.first().json;
const now = new Date().toISOString();
const token = String(cfg.mercadoLivreAccessToken || '').trim();
const userId = String(cfg.mercadoLivreUserId || '').trim();
const maxPromotions = Math.max(1, Math.min(Number(cfg.maxPromotions || 20), 50));
const limitPerPromotion = Math.max(1, Math.min(Number(cfg.limitPerPromotion || 50), 100));
const minDiscountPercent = Math.max(0, Number(cfg.minDiscountPercent || 0));
const allowedTypes = new Set(String(cfg.promotionTypes || '').split(',').map((type) => type.trim()).filter(Boolean));
const errors = [];

function basePayload(products = []) {
  return {
    runId: $execution?.id || `promocoes-${Date.now()}`,
    source: 'n8n',
    sourceName: 'Mercado Livre Promocoes',
    query: 'Promocoes ativas Mercado Livre',
    currency: 'BRL',
    products,
    errors,
    fetchedAt: now,
    monitorHubEndpoint: cfg.monitorHubEndpoint,
    monitorHubIngestToken: cfg.monitorHubIngestToken
  };
}

if (!token || !userId) {
  errors.push('n8n: preencha mercadoLivreAccessToken e mercadoLivreUserId no node Configuracao Promocoes.');
  return [{ json: basePayload([]) }];
}

function toNumber(value) {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  const raw = String(value).replace(/\s/g, '').replace(/R\$/gi, '').replace(/[^0-9,.-]/g, '');
  if (!raw) return null;
  const hasComma = raw.includes(',');
  const hasDot = raw.includes('.');
  let normalized = raw;
  if (hasComma && hasDot) normalized = raw.lastIndexOf(',') > raw.lastIndexOf('.') ? raw.replace(/\./g, '').replace(',', '.') : raw.replace(/,/g, '');
  else if (hasComma) normalized = raw.replace(',', '.');
  const number = Number(normalized);
  return Number.isFinite(number) ? number : null;
}

function statusValue(value) {
  return String(value?.id || value || '').toLowerCase();
}

function discountPercent(price, originalPrice) {
  if (!price || !originalPrice || originalPrice <= price) return 0;
  return Number((((originalPrice - price) / originalPrice) * 100).toFixed(2));
}

async function mlGet(path) {
  const response = await fetch(`https://api.mercadolibre.com${path}`, {
    headers: {
      Accept: 'application/json',
      Authorization: `Bearer ${token}`,
      'User-Agent': 'n8n-monitorhub-promocoes/1.0'
    }
  });
  const text = await response.text();
  let payload = null;
  try { payload = text ? JSON.parse(text) : null; } catch { payload = { raw: text }; }
  if (!response.ok) {
    const detail = payload?.message || payload?.error || payload?.raw || response.statusText;
    throw new Error(`HTTP ${response.status}: ${detail}`);
  }
  return payload;
}

let campaigns = [];
try {
  const campaignPayload = await mlGet(`/seller-promotions/users/${encodeURIComponent(userId)}?app_version=v2&limit=${maxPromotions}`);
  campaigns = (Array.isArray(campaignPayload?.results) ? campaignPayload.results : [])
    .filter((campaign) => statusValue(campaign.status) === 'started')
    .filter((campaign) => !allowedTypes.size || allowedTypes.has(String(campaign.type || '').trim()))
    .slice(0, maxPromotions);
} catch (error) {
  errors.push(`n8n: falha ao consultar promocoes do Mercado Livre (${error.message}).`);
  return [{ json: basePayload([]) }];
}

const promotedById = new Map();
for (const campaign of campaigns) {
  const promotionId = String(campaign.id || '').trim();
  const promotionType = String(campaign.type || '').trim();
  if (!promotionId || !promotionType) continue;

  try {
    const path = `/seller-promotions/promotions/${encodeURIComponent(promotionId)}/items?promotion_type=${encodeURIComponent(promotionType)}&status=started&app_version=v2&limit=${limitPerPromotion}`;
    const itemPayload = await mlGet(path);
    const items = Array.isArray(itemPayload?.results) ? itemPayload.results : [];

    for (const item of items) {
      const id = String(item.id || item.item_id || '').trim();
      const price = toNumber(item.price);
      const originalPrice = toNumber(item.original_price);
      const discount = discountPercent(price, originalPrice);
      if (!id || !price || !originalPrice || originalPrice <= price || discount < minDiscountPercent) continue;

      const previous = promotedById.get(id);
      if (previous && previous.discountPercent >= discount) continue;
      promotedById.set(id, {
        id,
        price,
        originalPrice,
        discountPercent: discount,
        promotionId,
        promotionType,
        promotionName: String(campaign.name || promotionType),
        promotionStatus: statusValue(item.status) || 'started'
      });
    }
  } catch (error) {
    errors.push(`n8n: falha ao consultar itens da promocao ${promotionId} (${error.message}).`);
  }
}

const promotedItems = [...promotedById.values()];
const detailsById = new Map();
for (let index = 0; index < promotedItems.length; index += 20) {
  const ids = promotedItems.slice(index, index + 20).map((item) => item.id);
  try {
    const detailPayload = await mlGet(`/items?ids=${ids.join(',')}`);
    const details = Array.isArray(detailPayload) ? detailPayload : [];
    for (const detail of details) {
      const body = detail?.body || detail;
      if (body?.id) detailsById.set(String(body.id), body);
    }
  } catch (error) {
    errors.push(`n8n: falha ao buscar detalhes de ${ids.length} itens (${error.message}).`);
  }
}

const products = promotedItems.map((promo) => {
  const detail = detailsById.get(promo.id) || {};
  const title = String(detail.title || promo.id);
  const url = String(detail.permalink || `https://produto.mercadolivre.com.br/${promo.id}`);
  return {
    id: promo.id,
    title,
    price: promo.price,
    originalPrice: promo.originalPrice,
    discountPercent: promo.discountPercent,
    currency: detail.currency_id || 'BRL',
    url,
    image: detail.secure_thumbnail || detail.thumbnail || detail.pictures?.[0]?.url || '',
    seller: detail.seller?.nickname || String(detail.seller_id || ''),
    availability: detail.available_quantity ? `${detail.available_quantity} disponivel` : String(detail.status || promo.promotionStatus),
    source: 'Mercado Livre Promocoes',
    sourceKind: 'mercadolivre',
    query: 'Promocoes ativas Mercado Livre',
    fetchedAt: now,
    opportunityScore: Math.min(100, Math.max(1, Math.round(70 + promo.discountPercent))),
    promotionId: promo.promotionId,
    promotionType: promo.promotionType,
    promotionName: promo.promotionName,
    notes: `${promo.promotionName} (${promo.promotionType}) - ${Math.round(promo.discountPercent)}% OFF`
  };
});

products.sort((a, b) => (b.discountPercent || 0) - (a.discountPercent || 0));
if (!products.length && !errors.length) {
  errors.push('n8n: nenhuma promocao ativa com preco promocional/original foi encontrada para esta conta.');
}

return [{ json: basePayload(products) }];
